+package middleware
+
+import (
+	"context"
+
+	"github.com/aws/aws-lambda-go/events"
+	"github.com/sitoo/go-utils-lambda/v2/alb/router"
+)
+
+type forwardedAuthorizationCtxKey struct{}
+
+// ForwardedAuthorizationToCtx is an ALB middleware that copies the inbound
+// Authorization header into request context.
+// Used to forward credentials to the IAM API.
+func ForwardedAuthorizationToCtx(next router.HandleFunc) router.HandleFunc {
+	return func(ctx context.Context, req *events.ALBTargetGroupRequest) (*events.ALBTargetGroupResponse, error) {
+		if hdr := router.GetHeaderValue(ctx, req, "Authorization"); hdr != "" {
+			ctx = context.WithValue(ctx, forwardedAuthorizationCtxKey{}, hdr)
+		}
+		return next(ctx, req)
+	}
+}
+
+// ForwardedAuthorizationFromCtx returns the previously-stored Authorization
+// header value or false if not present.
+func ForwardedAuthorizationFromCtx(ctx context.Context) (string, bool) {
+	v, ok := ctx.Value(forwardedAuthorizationCtxKey{}).(string)
+	return v, ok && v != ""
+}

