+
+func TestForwardedAuthorizationToCtx_StoresBasicHeader(t *testing.T) {
+	mw := ForwardedAuthorizationToCtx
+	called := false
+	next := func(ctx context.Context, req *events.ALBTargetGroupRequest) (*events.ALBTargetGroupResponse, error) {
+		called = true
+		got, ok := ForwardedAuthorizationFromCtx(ctx)
+		require.True(t, ok)
+		require.Equal(t, "Basic dXNlcjpwYXNz", got)
+		return &events.ALBTargetGroupResponse{StatusCode: 204}, nil
+	}
+	req := &events.ALBTargetGroupRequest{
+		Headers: map[string]string{"authorization": "Basic dXNlcjpwYXNz"},
+	}
+	ctx := router.WithRequestInfo(context.Background(), &router.RequestInfo{HasMultiValueHeaders: false})
+	_, err := mw(next)(ctx, req)
+	require.NoError(t, err)
+	require.True(t, called)
+}
