+// HTTPClient implements Client against a running IAM API.
+type HTTPClient struct {
+	baseURL string // e.g. "https://iam.sitooapis.com/v1"
+	hc      *http.Client
+}
+
+func NewHTTPClient(baseURL string, hc *http.Client) *HTTPClient {
+	if hc == nil {
+		hc = http.DefaultClient
+	}
+	return &HTTPClient{baseURL: baseURL, hc: hc}
+}
+
+type listUserAssignmentsResponse struct {
+	Items []struct {
+		UserID      string           `json:"user_id"`
+		Assignments []wireAssignment `json:"assignments"`
+	} `json:"items"`
+}
+
+type wireAssignment struct {
+	Source         string  `json:"source"`
+	AssignmentID   string  `json:"assignment_id"`
+	UserID         string  `json:"user_id"`
+	OrganizationID string  `json:"organization_id"`
+	Environment    string  `json:"environment"`
+	AccountIDs     []int64 `json:"account_ids"`
+	SiteIDs        []int64 `json:"site_ids"`
