+package iam
+
+import (
+	"context"
+	"sync"
+
+	"github.com/google/uuid"
+)
+
+// MockClient is an in-memory IAM Client for tests + local development.
+//
+// It is keyed by (organization_id, user_id) and stores Assignments
+// authored by UpsertAssignmentBySlug (or SeedLegacy). Filters on
+// SiteID/AccountID/StoreID match when the assignment's corresponding
+// scope slice contains the filter value (or always when filter is nil).
+type MockClient struct {
+	mu          sync.Mutex
+	assignments map[string]map[string][]Assignment // org -> user -> [assignments]
+}
+
+func NewMockClient() *MockClient {
+	return &MockClient{
+		assignments: make(map[string]map[string][]Assignment),
+	}
+}
+
+func (m *MockClient) ListUserAssignments(
+	_ context.Context,
+	_ string,
+	in ListUserAssignmentsInput,
+) ([]Assignment, error) {
+	m.mu.Lock()
+	defer m.mu.Unlock()
+
+	users := m.assignments[in.OrganizationID]
+	out := make([]Assignment, 0)
+	for _, uid := range in.UserIDs {
+		for _, a := range users[uid] {
+			if !matchScope(a, in) {
+				continue
+			}
+			out = append(out, a)
+		}
+	}
+	return out, nil
+}
+
+// SeedLegacy injects a synthetic legacy-source assignment. Used in tests
+// to verify read-merge precedence.
+func (m *MockClient) SeedLegacy(a Assignment) {
+	m.mu.Lock()
+	defer m.mu.Unlock()
+	a.Source = SourceLegacy
+	a.AssignmentID = ""
+	if m.assignments[a.OrganizationID] == nil {
+		m.assignments[a.OrganizationID] = make(map[string][]Assignment)
+	}
+	m.assignments[a.OrganizationID][a.UserID] = append(m.assignments[a.OrganizationID][a.UserID], a)
+}
+
+// AllAssignments returns every assignment currently held by the mock.
+// Used by tests to assert whether IAM was (or was not) called.
+func (m *MockClient) AllAssignments() []Assignment {
+	m.mu.Lock()
+	defer m.mu.Unlock()
+	var out []Assignment
+	for _, users := range m.assignments {
+		for _, group := range users {
+			out = append(out, group...)
+		}
+	}
+	return out
+}
+
+func (m *MockClient) UpsertAssignmentBySlug(
+	_ context.Context,
+	_ string,
+	in UpsertAssignmentBySlugInput,
+) ([]Assignment, error) {
+	m.mu.Lock()
+	defer m.mu.Unlock()
+
+	m.removeAtSiteLocked(in.OrganizationID, in.UserID, in.AccountID, in.SiteID)
+
+	if in.RoleSlug == "" {
+		return nil, nil
+	}
+
+	a := Assignment{
+		Source:         SourceIAM,
+		AssignmentID:   uuid.NewString(),
+		UserID:         in.UserID,
+		OrganizationID: in.OrganizationID,
+		Environment:    in.Environment,
+		AccountIDs:     []int64{in.AccountID},
+		SiteIDs:        []int64{in.SiteID},
+		StoreIDs:       append([]int64(nil), in.StoreIDs...),
+		RoleSlug:       in.RoleSlug,
+	}
+	if m.assignments[in.OrganizationID] == nil {
+		m.assignments[in.OrganizationID] = make(map[string][]Assignment)
+	}
+	m.assignments[in.OrganizationID][in.UserID] = append(
+		m.assignments[in.OrganizationID][in.UserID], a,
+	)
+	return []Assignment{a}, nil
+}
+
+// removeAtSiteLocked drops all assignments for the user at (account, site).
+// Caller must hold m.mu.
+func (m *MockClient) removeAtSiteLocked(org, user string, account, site int64) {
+	list := m.assignments[org][user]
+	if list == nil {
+		return
+	}
+	kept := list[:0]
+	for _, a := range list {
+		if !contains(a.AccountIDs, account) || !contains(a.SiteIDs, site) {
+			kept = append(kept, a)
+		}
+	}
+	m.assignments[org][user] = kept
+}
+
+func matchScope(a Assignment, in ListUserAssignmentsInput) bool {
+	if in.AccountID != nil && !contains(a.AccountIDs, *in.AccountID) {
+		return false
+	}
+	if in.SiteID != nil && !contains(a.SiteIDs, *in.SiteID) {
+		return false
+	}
+	if in.StoreID != nil && !contains(a.StoreIDs, *in.StoreID) {
+		return false
+	}
+	return true
+}
+
+func contains(xs []int64, v int64) bool {
+	for _, x := range xs {
+		if x == v {
+			return true
+		}
+	}
+	return false
+}

